/**
 * #nova-does-not-find-the-game — every folder that may hold the game, IN ORDER, each with where it came from; a candidate
 * counts only when the game's program is in it (hoi4.exe, or the Linux or Mac one: mod-index.js isHoi4GameFolder). A folder
 * Steam's own record names (a manifest, the registry) is listed even when it is not the game, with why, so Home can say it.
 * Pure: the registry, the drive list and the file system are handed in, so a test can
 * stand up any machine. `{ found, candidates }`: `found` is the first that holds the game, or null when none does (never a
 * folder that was not there); `candidates` are those asked, `{ path, source, where, how, valid, reason }`. Stops at the
 * first that holds the game unless `all`. Asked in this order:
 *   1. `choice` — the modder's own (Home → Game folder);   2. HOI4_ROOT;
 *   3. Steam's own record: the Steam folder from the registry (HKCU SteamPath, then HKLM Valve\Steam InstallPath in the 32-
 *      and the 64-bit view), every library its libraryfolders.vdf lists (the current format and the old one), and in each
 *      the appmanifest_394360.acf's installdir — the libraries whose "apps" name 394360 first, since a game moved to another
 *      library leaves the old list behind for a while;
 *   4. the Uninstall key Steam writes for 394360, in both views;
 *   5. what exists: the usual folders, the folders above Nova (`root`); then, slower, the usual Steam library folders on every
 *      local drive, the Xbox app's games folders (Game Pass: <drive>\XboxGames\…\Content, named by .GamingRoot), and a Linux
 *      Steam seen through Wine (its paths are Z:\…).
 * opts: { platform, env, choice, root, readRegistry(key, name, view "32"|"64"|"") → string|null, listDrives() → ["C:\\"…],
 *         fs: { existsSync, readFileSync, readdirSync }, all, scanFolders }
 * `scanFolders: false` stops after 4: no folder is looked for by its name (what NOVA_TEST_GAME_DETECTION asks for).
 */
function detectHoi4GameFolder(opts) {
  const o = opts || {};
  const platform = o.platform || process.platform;
  const win = platform === "win32";
  const P = win ? path.win32 : path.posix;
  const env = o.env || {};
  const fsx = o.fs || fs;
  const readRegistry = typeof o.readRegistry === "function" ? o.readRegistry : () => null;
  const listDrives = typeof o.listDrives === "function" ? o.listDrives : () => [];
  const APP = HOI4_STEAM_APP_ID;
  const exists = (p) => { try { return !!p && fsx.existsSync(p); } catch (_) { return false; } };
  const readText = (p) => { try { return String(fsx.readFileSync(p, "utf8")); } catch (_) { return null; } };
  const trimSep = (p) => { let s = String(p || ""); while (s.length > 1 && /[\\/]$/.test(s) && P.parse(s).root !== s) s = s.slice(0, -1); return s; };
  const keyOf = (p) => (win ? trimSep(P.normalize(p)).toLowerCase() : trimSep(P.normalize(p)));
  // A Linux Steam's own files name Linux paths; seen from a Windows program under Wine they are under Z:.
  const fromUnix = (p) => (win && /^\//.test(String(p || "")) ? "Z:" + String(p).replace(/\//g, "\\") : String(p || ""));
  const candidates = [];
  const seen = new Set();
  let found = null;
  /** Offer one folder; true when the search is over. A `quiet` miss is not listed (a scan of every drive would list dozens). */
  const offer = (dir, source, where, how, quiet) => {
    if (found && !o.all) return true;
    const raw = String(dir || "").trim();
    if (!raw) return false;
    if (!P.isAbsolute(raw)) {
      if (!quiet) candidates.push({ path: raw, source, where, how: how || "", valid: false, reason: "not a full folder address" });
      return false;
    }
    const p = trimSep(P.normalize(raw));
    const k = keyOf(p);
    if (seen.has(k)) return false;
    const valid = isHoi4GameFolder(p, exists, P.join);
    if (!valid && quiet) return false;
    seen.add(k);
    const c = { path: p, source, where, how: how || "", valid, reason: valid ? "" : (exists(p) ? `there is no ${HOI4_GAME_EXE} in it` : "there is no such folder") };
    candidates.push(c);
    if (valid && !found) found = c;
    return !!found && !o.all;
  };
  // Every library a Steam folder knows of: itself first, then each its libraryfolders.vdf lists.
  const steamLibraries = (steamDir) => {
    const out = [];
    const add = (dir, apps, fromVdf) => {
      const d = trimSep(P.normalize(fromUnix(String(dir || "").trim())));
      if (!d || !P.isAbsolute(d)) return;
      const had = out.find((l) => keyOf(l.dir) === keyOf(d));
      if (had) { if (apps && !had.apps) had.apps = apps; if (fromVdf) had.dir = d; return; }   // the list's spelling: SteamPath is lower case
      out.push({ dir: d, apps: apps || null });
    };
    add(steamDir, null, false);
    for (const rel of [["steamapps", "libraryfolders.vdf"], ["config", "libraryfolders.vdf"]]) {
      const t = readText(P.join(steamDir, ...rel));
      if (t !== null) for (const lib of steamLibraryFoldersFromVdf(t)) add(lib.path, lib.apps, true);
    }
    return out;
  };
  const triedSteam = new Set();
  /** The game in a Steam folder's libraries: by each library's manifest, then by the folder's usual name. A folder a manifest
   *  names is Steam's own record that the game is there, so it is listed with why when it is not (#nova-does-not-find-the-game:
   *  on every route, the quiet ones too — a drive scan or Wine's Linux Steam is where an odd install turns up); the guess by
   *  the usual name is listed only when it is the game. */
  const fromSteamFolder = (steamDir, source, how) => {
    const s = trimSep(P.normalize(fromUnix(String(steamDir || "").trim())));
    if (!s || !P.isAbsolute(s) || triedSteam.has(keyOf(s))) return false;
    triedSteam.add(keyOf(s));
    if (!exists(s)) return false;
    const libs = steamLibraries(s);
    const claims = (l) => !!(l.apps && l.apps.has(APP));
    const ordered = [...libs.filter(claims), ...libs.filter((l) => !claims(l))];
    for (const lib of ordered) {
      const acf = P.join(lib.dir, "steamapps", `appmanifest_${APP}.acf`);
      const text = readText(acf);
      if (text === null) continue;
      const installdir = steamAppInstallDir(text) || "Hearts of Iron IV";
      if (offer(P.join(lib.dir, "steamapps", "common", installdir), source, `the Steam library ${lib.dir}`, `${how}; ${acf}`, false)) return true;
    }
    // A library's game folder without a manifest: copied in by hand, or a manifest Steam has lost.
    for (const lib of ordered) {
      if (offer(P.join(lib.dir, "steamapps", "common", "Hearts of Iron IV"), source, `the Steam library ${lib.dir}`, `${how}; no appmanifest_${APP}.acf`, true)) return true;
    }
    return false;
  };
  const UNINSTALL = `HKLM\\SOFTWARE\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\Steam App ${APP}`;
  const stages = [
    () => offer(o.choice, "choice", "the folder you chose", "Home → Game folder"),
    () => offer(env.HOI4_ROOT, "env", "the HOI4_ROOT setting", "HOI4_ROOT"),
    () => {
      if (!win) return false;
      for (const [key, name, view, how] of [
        ["HKCU\\Software\\Valve\\Steam", "SteamPath", "", "HKCU\\Software\\Valve\\Steam SteamPath"],
        ["HKLM\\SOFTWARE\\Valve\\Steam", "InstallPath", "32", "HKLM\\SOFTWARE\\WOW6432Node\\Valve\\Steam InstallPath (32-bit view)"],
        ["HKLM\\SOFTWARE\\Valve\\Steam", "InstallPath", "64", "HKLM\\SOFTWARE\\Valve\\Steam InstallPath (64-bit view)"],
      ]) {
        let v = null;
        try { v = readRegistry(key, name, view); } catch (_) { v = null; }
        if (v && fromSteamFolder(String(v), "steam", how)) return true;
      }
      return false;
    },
    () => {
      if (!win) return false;
      for (const view of ["64", "32"]) {
        let v = null;
        try { v = readRegistry(UNINSTALL, "InstallLocation", view); } catch (_) { v = null; }
        if (v && offer(String(v), "steam-uninstall", "Windows' list of installed programs", `${UNINSTALL} InstallLocation (${view}-bit view)`)) return true;
      }
      return false;
    },
    () => {
      if (!win || o.scanFolders === false) return false;
      const pf86 = env["ProgramFiles(x86)"] || "C:\\Program Files (x86)";
      const pf = env.ProgramW6432 || env.ProgramFiles || "C:\\Program Files";
      for (const d of [
        P.join(pf86, "Steam", "steamapps", "common", "Hearts of Iron IV"),
        P.join(pf, "Steam", "steamapps", "common", "Hearts of Iron IV"),
        "C:\\Program Files (x86)\\Steam\\steamapps\\common\\Hearts of Iron IV",
        "C:\\Program Files\\Steam\\steamapps\\common\\Hearts of Iron IV",
        "D:\\SteamLibrary\\steamapps\\common\\Hearts of Iron IV",
        "E:\\SteamLibrary\\steamapps\\common\\Hearts of Iron IV",
        "F:\\SteamLibrary\\steamapps\\common\\Hearts of Iron IV",
      ]) if (offer(d, "usual", "a usual install folder", "", true)) return true;
      // …and a usual Steam folder's own library list, for a Steam that left no record in the registry.
      for (const s of [P.join(pf86, "Steam"), P.join(pf, "Steam")]) if (fromSteamFolder(s, "steam", `the usual Steam folder ${s}`)) return true;
      return false;
    },
    () => {
      // The folders above Nova, as resolveHoi4GameRoot always walked: a Nova kept inside the game's folder.
      if (o.scanFolders === false) return false;
      let dir = o.root ? P.resolve(String(o.root)) : "";
      for (let i = 0; dir && i < 28; i++) {
        if (offer(dir, "nova", "a folder above Nova", "", true)) return true;
        const up = P.dirname(dir);
        if (up === dir) break;
        dir = up;
      }
      return false;
    },
    () => {
      // ⏱ The slow route, only when everything above found nothing: every local drive's usual library folders and the
      // Xbox app's games folders, then a Linux Steam seen through Wine; on another system, that system's Steam folders.
      if (o.scanFolders === false) return false;
      if (win) {
        let drives = [];
        try { drives = listDrives() || []; } catch (_) { drives = []; }
        for (const d of drives) {
          const root = String(d).replace(/[\\/]*$/, "\\");
          for (const lib of ["SteamLibrary", "Steam", "Games\\Steam", "Games\\SteamLibrary", "Program Files (x86)\\Steam", "Program Files\\Steam"]) {
            if (fromSteamFolder(P.join(root, lib), "steam", `a Steam folder on ${root}`)) return true;
          }
          for (const games of xboxGamesFolders(root, fsx, P)) {
            let names = [];
            try { names = fsx.readdirSync(games); } catch (_) { names = []; }
            for (const name of names) {
              if (!/hearts\s*of\s*iron/i.test(String(name))) continue;
              if (offer(P.join(games, String(name), "Content"), "xbox", "the Xbox app's games folder", games)) return true;
              if (offer(P.join(games, String(name)), "xbox", "the Xbox app's games folder", games)) return true;
            }
          }
        }
        const home = (() => {
          const w = String(env.WINEHOMEDIR || "").replace(/^\\\?\?\\/, "");
          if (/^[A-Za-z]:\\/.test(w)) return w;
          return /^\//.test(String(env.HOME || "")) ? fromUnix(env.HOME) : "";
        })();
        if (home) {
          // Linux Steam (native, or Flatpak), and a Mac's under CrossOver, whose Wine maps / to Z: as well
          for (const s of [P.join(home, ".steam", "steam"), P.join(home, ".local", "share", "Steam"), P.join(home, ".var", "app", "com.valvesoftware.Steam", ".local", "share", "Steam"),
            P.join(home, "Library", "Application Support", "Steam")]) {
            if (fromSteamFolder(s, "steam", `the Steam folder ${s}`)) return true;
          }
        }
        return false;
      }
      const home = String(env.HOME || "");
      if (!home) return false;
      for (const s of [
        env.XDG_DATA_HOME ? P.join(String(env.XDG_DATA_HOME), "Steam") : "",
        P.join(home, ".steam", "steam"), P.join(home, ".local", "share", "Steam"),
        P.join(home, ".var", "app", "com.valvesoftware.Steam", ".local", "share", "Steam"),
        P.join(home, "Library", "Application Support", "Steam"),
      ]) if (s && fromSteamFolder(s, "steam", `the Steam folder ${s}`)) return true;
      return false;
    },
  ];
  for (const stage of stages) { if (stage()) break; }
  return { found, candidates };
}

/** A Steam KeyValues text (libraryfolders.vdf, appmanifest_*.acf) as [key, value] pairs; a value is a string or more pairs. */
function parseSteamKeyValues(text) {
  const s = String(text || "").replace(/^\uFEFF/, "");
  const n = s.length;
  let i = 0;
  const token = () => {
    for (;;) {
      while (i < n && /\s/.test(s[i])) i++;
      if (i >= n) return null;
      if (s[i] === "/" && s[i + 1] === "/") { while (i < n && s[i] !== "\n") i++; continue; }
      break;
    }
    const c = s[i];
    if (c === "{" || c === "}") { i++; return { t: c }; }
    let out = "";
    if (c === "\"") {
      i++;
      while (i < n && s[i] !== "\"") {
        if (s[i] === "\\" && i + 1 < n) { const d = s[i + 1]; out += d === "n" ? "\n" : d === "t" ? "\t" : d; i += 2; continue; }
        out += s[i++];
      }
      i++;
      return { t: "s", v: out };
    }
    while (i < n && !/[\s{}"]/.test(s[i])) out += s[i++];
    return { t: "s", v: out };
  };
  const block = (depth) => {
    const pairs = [];
    for (;;) {
      const k = token();
      if (!k || k.t === "}") return pairs;
      if (k.t === "{") { if (depth < 64) block(depth + 1); continue; }
      const v = token();
      if (!v) { pairs.push([k.v, ""]); return pairs; }
      if (v.t === "{") pairs.push([k.v, depth < 64 ? block(depth + 1) : []]);
      else if (v.t === "}") { pairs.push([k.v, ""]); return pairs; }
      else pairs.push([k.v, v.v]);
      const at = i, cond = token();          // a platform condition after a value: "key" "value" [$WIN32]
      if (!(cond && cond.t === "s" && /^\[.*\]$/.test(cond.v))) i = at;
    }
  };
  return block(0);
}
function steamKeyValue(pairs, name) {
  if (!Array.isArray(pairs)) return undefined;
  const want = String(name).toLowerCase();
  const hit = pairs.find(([k]) => String(k).toLowerCase() === want);
  return hit ? hit[1] : undefined;
}
/** Every library a libraryfolders.vdf lists: `"N" { "path" "…" "apps" { "394360" … } }` now, `"N" "D:\\SteamLibrary"` before 2021. */
function steamLibraryFoldersFromVdf(text) {
  const top = steamKeyValue(parseSteamKeyValues(text), "libraryfolders");
  if (!Array.isArray(top)) return [];
  const out = [];
  for (const [k, v] of top) {
    if (!/^\d+$/.test(String(k))) continue;        // TimeNextStatsReport, ContentStatsID: not libraries
    if (typeof v === "string") { if (v.trim()) out.push({ path: v, apps: null }); continue; }
    const p = steamKeyValue(v, "path");
    if (typeof p !== "string" || !p.trim()) continue;
    const apps = steamKeyValue(v, "apps");
    out.push({ path: p, apps: Array.isArray(apps) ? new Set(apps.map(([id]) => String(id))) : null });
  }
  return out;
}
/** The folder under steamapps\common an appmanifest names, or "". */
function steamAppInstallDir(text) {
  const d = steamKeyValue(steamKeyValue(parseSteamKeyValues(text), "AppState"), "installdir");
  return typeof d === "string" ? d.trim() : "";
}
/** The Xbox app's games folders on one drive: what its .GamingRoot names ("RGBX", a count, UTF-16 paths), and XboxGames. */
function xboxGamesFolders(driveRoot, fsx, P) {
  const out = [];
  let buf = null;
  try { buf = fsx.readFileSync(P.join(driveRoot, ".GamingRoot")); } catch (_) { buf = null; }
  if (buf && Buffer.isBuffer(buf) && buf.length >= 8 && buf.toString("latin1", 0, 4) === "RGBX") {
    for (const rel of buf.slice(8).toString("utf16le").split("\u0000")) {
      const r = rel.trim();
      if (r) out.push(P.isAbsolute(r) ? r : P.join(driveRoot, r));
    }
  }
  out.push(P.join(driveRoot, "XboxGames"));
  return [...new Set(out)];
}

/** A REG_SZ / REG_EXPAND_SZ value as text, with %NAME% filled from the environment where it can be. */
function expandWindowsEnvVars(s) {
  return String(s || "").replace(/%([^%]+)%/g, (all, name) => {
    const key = Object.keys(process.env).find((k) => k.toUpperCase() === String(name).toUpperCase());
    return key && process.env[key] ? process.env[key] : all;
  });
}
