// Bundle every HOI4 log + the newest crash dump(s) into one report. This is the "diagnostic tool":
// the game already writes the detail (incl. the crash's exception.txt with the access-violation +
// stack trace) — users just don't know to send it. This gathers it all in one click.
function collectHoi4Diagnostics() {
  const userDir = resolveHoi4UserDir();
  if (!userDir) {
    const named = folderVariableNamingNoFolder(["HOI4_USER_DIR"]);   // #a-variable-that-names-no-folder
    return { ok: false, error: named ? `${named}, so there is nothing to collect. Correct it, or clear it to use the folder the game's launcher names.`
      : "Could not find your Hearts of Iron IV user folder (Documents/Paradox Interactive/Hearts of Iron IV). Set HOI4_USER_DIR if it's elsewhere." };
  }
  const PER_FILE_CAP = 60000;
  const out = [];
  out.push("===== NOVA HOI4 DIAGNOSTICS =====");
  out.push("collected: " + new Date().toISOString());
  out.push("user dir:  " + userDir);
  // ⛔ #the-report-says-what-it-could-not-read — every read below skipped its failure, so a log the game held locked read as "no non-empty
  // logs", and an unreadable crashes folder as "the game didn't hard-crash" (review S4). What is simply not there is no failure.
  const unread = [];
  const couldNotRead = (what, e) => {
    if (e && e.code === "ENOENT") return "";
    const why = `${what}: ${(e && e.message) || e}`;
    unread.push(why);
    return why;
  };

  // 1) Crash dumps (newest first) — exception.txt names the actual crash; dlc_load.json shows the mods.
  const crashesDir = path.join(userDir, "crashes");
  let crashes = [];
  let crashesUnread = "";
  try {
    crashes = fs.readdirSync(crashesDir, { withFileTypes: true })
      .filter((d) => d.isDirectory())
      .map((d) => { let t = 0; try { t = fs.statSync(path.join(crashesDir, d.name)).mtimeMs; } catch (_) {} return { name: d.name, t }; })
      .sort((a, b) => b.t - a.t);
  } catch (e) { crashesUnread = couldNotRead("crashes", e); }
  out.push("\n===== CRASH DUMPS (" + crashes.length + " total; newest first) =====");
  if (crashesUnread) out.push("(could not read " + crashesUnread + ")");
  else if (!crashes.length) out.push("(none — the game didn't hard-crash this session)");
  for (const cf of crashes.slice(0, 3)) {
    out.push("\n--- " + cf.name + " ---");
    for (const fn of ["exception.txt", "meta.yml", "dlc_load.json"]) {
      try { const t = fs.readFileSync(path.join(crashesDir, cf.name, fn), "utf8").trim(); if (t) out.push("[" + fn + "]\n" + t); }
      catch (e) { const why = couldNotRead(path.join("crashes", cf.name, fn), e); if (why) out.push("(could not read " + why + ")"); }
    }
  }

  // 2) Every non-empty log file.
  const logsDir = path.join(userDir, "logs");
  out.push("\n===== LOGS =====");
  const unreadBeforeLogs = unread.length;
  let logFiles = [];
  try { logFiles = fs.readdirSync(logsDir).filter((f) => /\.(log|txt)$/i.test(f)); }
  catch (e) { const why = couldNotRead("logs", e); if (why) out.push("(could not read " + why + ")"); }
  let included = 0;
  for (const f of logFiles) {
    let txt = "";
    try { txt = fs.readFileSync(path.join(logsDir, f), "utf8"); }
    catch (e) { const why = couldNotRead(path.join("logs", f), e); if (why) out.push("\n----- could not read " + why + " -----"); continue; }
    if (!txt.trim()) continue;
    included++;
    let body = txt.length > PER_FILE_CAP ? ("…(truncated; last " + PER_FILE_CAP + " chars)…\n" + txt.slice(-PER_FILE_CAP)) : txt;
    out.push("\n----- " + f + " (" + txt.length + " bytes) -----\n" + body.trim());
  }
  if (!included && unread.length === unreadBeforeLogs) out.push("(no non-empty logs found)");

  const report = out.join("\n");
  // #the-report-says-whether-its-copy-was-saved — savedPath is "" when the copy could not be written (a folder of that name in
  // the way, a read-only folder), and Home then said "Saved a copy to your HOI4 folder" (review R8). saveError says why.
  // ⛔ #nothing-to-report-keeps-the-last-report — with no crash dump and no log there is nothing to keep a copy of: it said a green "✓ Saved a
  // copy" and replaced the report of the last crash with one saying nothing, for good (review S4). That report stays, and Home says where.
  const nothingToReport = !crashes.length && !included;
  let savedPath = "", saveError = "", earlierReport = "";
  if (nothingToReport) {
    const earlier = path.join(userDir, "nova_diagnostics.txt");
    try { if (fs.statSync(earlier).isFile()) earlierReport = earlier; } catch (_) { /* there is no earlier report */ }
  } else {
    try { savedPath = path.join(userDir, "nova_diagnostics.txt"); fs.writeFileSync(savedPath, report, "utf8"); }
    catch (e) { savedPath = ""; saveError = String((e && e.message) || e); }
  }
  return { ok: true, userDir, crashCount: crashes.length, latestCrash: crashes[0] ? crashes[0].name : null, savedPath, saveError, report, nothingToReport, earlierReport, unread };
}

const DEFAULT_FOCUS_PATH = "";
const WORKSHOP_MOD_DIRS = [];

const WORKSHOP_MOD_DIR_CACHE_MS = 60 * 1000;
let workshopModDirCache = { at: 0, dirs: [] };
// #ideas-catalog-stale-ttl — this was 24 HOURS, and the TTL is checked BEFORE the disk fingerprint, so the
