// #catalog-race-refills-stale — the in-memory catalog was served on its TTL alone, unlike the disk copy which
// is validated against a file fingerprint. Two things went wrong because of that:
//
//   * a save during the TTL window was invisible until the window expired, and
//   * worse, a catalog request already in flight when the save landed went on to STORE the items it had
//     computed from the pre-write files — after the save had cleared the cache. The invalidation was undone by
//     a request that started before it, so the new spirit stayed missing from the picker for the whole session.
//
// An epoch counter fixes both: the request captures it at the start, and the store is skipped if a write has
// bumped it in the meantime. Same idiom as localizationWriteEpoch above.
let ideasCatalogEpoch = 0;

function clearIdeasCatalogCache() {
  try {
    ideasCatalogEpoch++;
    ideasCatalogCache.clear();
    if (fs.existsSync(ICON_CACHE_DIR)) {
      const files = fs.readdirSync(ICON_CACHE_DIR);
      files.forEach((f) => {
        if (f.startsWith("ideacatalog_") && f.endsWith(".json")) {
          try {
            fs.unlinkSync(path.join(ICON_CACHE_DIR, f));
          } catch (_) {}
        }
      });
    }
  } catch (_e) {
    // ignore
  }
}

function ideasCatalogCacheKey(parts) {
  const srcPath = String(parts.sourcePath || "").trim();
  const includeActiveMod = parts.includeActiveMod ? "1" : "0";
  const includeVanilla = parts.includeVanilla ? "1" : "0";
  const includeWorkshop = parts.includeWorkshop ? "1" : "0";
  const includeModsRoot = parts.includeModsRoot ? "1" : "0";
  const activeRoot = String(parts.activeRoot || "").trim().toLowerCase();
  const gameRoot = String(parts.gameRoot || "").trim().toLowerCase();
  const workshopRoot = String(parts.workshopRoot || "").trim().toLowerCase();
  // The catalog folds in the active mod's DEPENDENCY ideas (e.g. Millennium Dawn), so the dependency set is
  // part of the identity — otherwise editing descriptor.mod's dependencies served a stale catalog for the
  // same activeRoot.
  const deps = (Array.isArray(parts.deps) ? parts.deps : []).map((d) => String(d || "").trim().toLowerCase()).filter(Boolean).sort().join("|");
  return [
    // #replace-path-ideas — bump when the SET OF ROOTS the catalog scans changes meaning, or a payload cached
    // under the old rule is served under the new one. v2 = vanilla is dropped when the chain replace_path's
    // common/ideas.
    "v2",
    includeActiveMod,
    includeVanilla,
    includeWorkshop,
    includeModsRoot,
    activeRoot,
    gameRoot,
    workshopRoot,
    deps,
    srcPath.toLowerCase(),
  ].join("::");
}

/** Any workshop item folder under Steam's HOI4 workshop app id (394360), or HOI4_WORKSHOP_ROOT when set. */
function getSteamHoi4WorkshopContentRootForVerify() {
  const env = process.env.HOI4_WORKSHOP_ROOT && String(process.env.HOI4_WORKSHOP_ROOT).trim();
  if (env) {
    try {
      const r = path.resolve(env);
      if (fs.existsSync(r) && fs.statSync(r).isDirectory()) return r;
    } catch (_e) {
      // ignore
    }
  }
  try {
    if (WORKSHOP_ROOT && fs.existsSync(WORKSHOP_ROOT) && fs.statSync(WORKSHOP_ROOT).isDirectory()) {
      return path.resolve(WORKSHOP_ROOT);
    }
  } catch (_e) {
    // ignore
  }
  return null;
}

function getHoi4ExtraContentDirs() {
  const gameRoot = resolveHoi4GameRoot();
  if (!gameRoot) return [];
  const dirs = [];
  const addSubdirsOf = (parentDirName) => {
    const parentPath = path.join(gameRoot, parentDirName);
    if (fs.existsSync(parentPath)) {
      try {
        const ents = fs.readdirSync(parentPath, { withFileTypes: true });
        ents.forEach(ent => {
          if (ent.isDirectory()) {
            dirs.push(path.join(parentPath, ent.name));
          }
        });
      } catch (_) {}
    }
  };
  addSubdirsOf("dlc");
  addSubdirsOf("integrated_dlc");
  return dirs;
}

// Module-level dependency resolver for ASSET roots (sprite/icon scans live in module scope, where
// the createApp-scoped resolveModDependencyRoots isn't visible). Reads the active mod's descriptor
// dependencies={ "..." } and maps each declared base mod (e.g. Millennium Dawn) to its on-disk root
// by matching descriptor `name`. Returns [] for vanilla or a mod with no dependencies, so callers
// are unchanged in the common case.
// Resolve dependency NAMES (as they appear in a descriptor's dependencies block) to installed mod roots.
// Split out of resolveDependencyRootsForAssets so a caller that has the names but no descriptor to read
// them from can use it too — /api/mod/create-template validates its capital state before the mod it is
// about to create exists on disk. #capital-must-exist
function resolveDependencyRootsByNames(names) {
  try {
    const wanted = (Array.isArray(names) ? names : []).map((n) => String(n || "").trim()).filter(Boolean);
    if (!wanted.length) return [];
    const byName = new Map();
    const add = (dir) => {
      if (!dir || !fs.existsSync(dir)) return;
      const d2 = path.join(dir, "descriptor.mod");
      if (!fs.existsSync(d2)) return;
      try {
        const mm = fs.readFileSync(d2, "utf8").match(/\bname\s*=\s*"(.*?)"/);
        if (mm && !byName.has(mm[1])) byName.set(mm[1], dir);
      } catch (_) {}
    };
    // #two-documents-folders — the folders that ARE mods, not every subfolder of mod\: a copy carries the same name.
    listModFolderCandidates().forEach(add);
    return wanted.map((n) => byName.get(n)).filter((p) => p && fs.existsSync(p));
  } catch (_) {
    return [];
  }
}

function resolveDependencyRootsForAssets(activeRoot) {
  return resolveDependencyRootsByNames(declaredDependencyNames(activeRoot));
}

/** The base mods a descriptor.mod DECLARES, whether or not they are installed. */
function declaredDependencyNames(activeRoot) {
  try {
    if (!activeRoot || typeof activeRoot !== "string") return [];
    const dp = path.join(activeRoot, "descriptor.mod");
    if (!fs.existsSync(dp)) return [];
    const depBlock = /\bdependencies\s*=\s*\{([\s\S]*?)\}/.exec(fs.readFileSync(dp, "utf8"));
    if (!depBlock) return [];
    return (depBlock[1].match(/"([^"]+)"/g) || []).map((s) => s.replace(/"/g, "").trim()).filter(Boolean);
  } catch (_) {
    return [];
  }
}

// ⛔ #addon-copies-vanillas-gui — "NO DEPENDENCIES" AND "DEPENDENCIES MISSING" ARE NOT THE SAME ANSWER.
