// ── Self-updating model discovery ──────────────────────────────────────────
// Rather than hardcode versions (which break when Google retires models like 1.5), ASK
// Google which models the key can actually use, then rank them. Cached per-key for an hour.
// Falls back to GEMINI_MODELS if the ListModels call fails. This makes the app auto-adopt
// new Gemini versions and auto-skip retired ones with no code changes.
const geminiModelCache = new Map(); // key -> { at: number, models: string[] }
const GEMINI_MODEL_TTL_MS = 60 * 60 * 1000;

// Score a model name for "best for our use" — fast text generation. Higher = preferred.
function scoreGeminiModel(name) {
  const n = name.toLowerCase();
  let s = 0;
  if (n.includes("-latest")) s += 1000;          // auto-tracking alias = most future-proof
  const ver = n.match(/gemini-(\d+)\.(\d+)/);     // newer version family first
  if (ver) s += Number(ver[1]) * 100 + Number(ver[2]) * 10;
  if (n.includes("flash") && !n.includes("flash-lite")) s += 50; // flash = fast+free-tier friendly
  if (n.includes("flash-lite")) s += 30;
  if (n.includes("pro")) s += 20;                 // pro = capable but stricter free-tier limits
  // Avoid non-text / preview / experimental variants for production use.
  if (n.includes("vision") || n.includes("embedding") || n.includes("aqa") || n.includes("imagen") || n.includes("tts") || n.includes("image")) s -= 5000;
  if (n.includes("exp") || n.includes("preview") || n.includes("-thinking")) s -= 200;
  return s;
}

async function getGeminiModels(apiKey) {
  if (!apiKey) return GEMINI_MODELS;
  const cached = geminiModelCache.get(apiKey);
  if (cached && Date.now() - cached.at < GEMINI_MODEL_TTL_MS) return cached.models;
  try {
    const controller = new AbortController();
    const to = setTimeout(() => { try { controller.abort(); } catch (_) {} }, 8000);
    const resp = await fetch(`https://generativelanguage.googleapis.com/v1beta/models?key=${apiKey}`, { signal: controller.signal });
    clearTimeout(to);
    const data = await resp.json();
    if (data && Array.isArray(data.models)) {
      const usable = data.models
        .filter((m) => Array.isArray(m.supportedGenerationMethods) && m.supportedGenerationMethods.includes("generateContent"))
        .map((m) => String(m.name || "").replace(/^models\//, ""))
        .filter((n) => n.startsWith("gemini"))
        .sort((a, b) => scoreGeminiModel(b) - scoreGeminiModel(a));
      if (usable.length) {
        // Keep a sensible cap; the top few are all we ever try per request.
        const ranked = usable.slice(0, 6);
        geminiModelCache.set(apiKey, { at: Date.now(), models: ranked });
        return ranked;
      }
    }
  } catch (_e) { /* fall through to hardcoded */ }
  return GEMINI_MODELS;
}

// Core HOI4 trigger/effect syntax rules. The focus-reward default prompt has a full 36-rule
