    const clean = (s) => String(s).replace(/§[A-Za-z0-9!]/g, "").replace(/\[[^\]]*\]/g, "").replace(/£\S+/g, "").replace(/\s{2,}/g, " ").trim();
    // The $alias$ chasing lives in resolveLocValue now — one rule, shared with the decisions list, rather
    // than a fourth private copy of it. This keeps the token fallback, which is MIO-specific.
    // #pickers-show-raw-tokens
    const nameOf = (tok) => {
      const raw = tok != null ? loc[tok] : null;
      if (raw == null) return String(tok || "").replace(/_/g, " ");
      return clean(resolveLocValue((k) => loc[k], raw)) || String(tok).replace(/_/g, " ");
    };
