          // `include = X` (e.g. USA marmon_herrington → generic_mobile_tank_organization) instead of
          // declaring them. Capture the include so a second pass can resolve it — without this, every
          // country's real named companies were missed and only the generics showed. #mio-include
          const include = (/(?:^|\n)\s*include\s*=\s*([A-Za-z_][A-Za-z0-9_]*)/.exec(body) || [])[1] || "";
          if (!categories.length && !directArchetypes.length && !include) continue; // neither builds nor inherits → not a manufacturer
          const icon = (/(?:^|\n)\s*icon\s*=\s*([A-Za-z_][A-Za-z0-9_.-]*)/.exec(body) || [])[1] || "";
