    // company directly) still get returned — the endpoint's ranking sorts real/owner companies to the top,
    // and a generic template is a legitimate manufacturer choice anyway. Drop only entries that STILL have no
    // categories after resolution (a broken include).
    const out = [...byId.values()].filter((m) => m.categories.length || m.directArchetypes.length);
    _mioAllCache.set(cacheKey, { fingerprint, result: out });
